#pragma warning disable CA1725
using Microsoft.EntityFrameworkCore;using WhatsBiz.Application.Common.Interfaces;using WhatsBiz.Domain.Suppliers;
namespace WhatsBiz.Infrastructure.Persistence;
public sealed class SupplierRepository(ApplicationDbContext db):ISupplierRepository{public async Task<(IReadOnlyCollection<Supplier>,int)> SearchAsync(string? search,bool? active,string sort,bool desc,int page,int size,CancellationToken t){var q=db.Suppliers.AsNoTracking().Where(x=>!x.IsDeleted);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.SupplierCode.Contains(search)||x.SupplierName.Contains(search)||(x.GSTIN!=null&&x.GSTIN.Contains(search))||(x.Mobile!=null&&x.Mobile.Contains(search)));if(active.HasValue)q=q.Where(x=>x.IsActive==active);q=(sort.ToLowerInvariant(),desc) switch{("suppliercode",false)=>q.OrderBy(x=>x.SupplierCode),("suppliercode",true)=>q.OrderByDescending(x=>x.SupplierCode),("creditlimit",false)=>q.OrderBy(x=>x.CreditLimit),("creditlimit",true)=>q.OrderByDescending(x=>x.CreditLimit),(_,true)=>q.OrderByDescending(x=>x.SupplierName),_=>q.OrderBy(x=>x.SupplierName)};var count=await q.CountAsync(t);return(await q.Skip((page-1)*size).Take(size).ToArrayAsync(t),count);}public Task<Supplier?> GetAsync(Guid id,bool tracking,CancellationToken t){var q=db.Suppliers.Include(x=>x.PaymentTerm).Include(x=>x.Contacts).Include(x=>x.Addresses).Include(x=>x.BankAccounts).Include(x=>x.Documents).Where(x=>!x.IsDeleted);if(!tracking)q=q.AsNoTracking();return q.SingleOrDefaultAsync(x=>x.SupplierId==id,t);}public Task<bool> DuplicateAsync(string code,string? gstin,string name,Guid? exclude,CancellationToken t)=>db.Suppliers.AnyAsync(x=>!x.IsDeleted&&(!exclude.HasValue||x.SupplierId!=exclude)&&(x.SupplierCode==code.Trim()||x.SupplierName==name.Trim()||(!string.IsNullOrWhiteSpace(gstin)&&x.GSTIN==gstin.Trim())),t);public async Task<IReadOnlyCollection<SupplierPaymentTerm>> PaymentTermsAsync(CancellationToken t)=>await db.SupplierPaymentTerms.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.DueDays).ToArrayAsync(t);public void Add(Supplier s)=>db.Suppliers.Add(s);public void RemoveChildren(Supplier s){db.SupplierContacts.RemoveRange(s.Contacts);db.SupplierAddresses.RemoveRange(s.Addresses);db.SupplierBankAccounts.RemoveRange(s.BankAccounts);s.Contacts=[];s.Addresses=[];s.BankAccounts=[];}public Task<SupplierDocument?> DocumentAsync(Guid sid,Guid did,bool tracking,CancellationToken t){var q=db.SupplierDocuments.Where(x=>x.SupplierId==sid&&x.DocumentId==did&&!x.IsDeleted);if(!tracking)q=q.AsNoTracking();return q.SingleOrDefaultAsync(t);}public void Add(SupplierDocument d)=>db.SupplierDocuments.Add(d);public Task SaveAsync(CancellationToken t)=>db.SaveChangesAsync(t);}
